import { Color, RNG } from "rot-js";
import Being from "./being.js";
import * as items from "../item/items.js";
import * as rules from "../rules.js";
import * as ai from "../ai.js";
import * as pubsub from "../util/pubsub.js";

// Every creature that is not the player: the bugs that infest the tower,
// and the colleagues who are hunting them too. Classes with a static
// `danger` can be generated by the factory on a layer of roughly that
// danger.

const COLLEAGUE_LEVELS = [
  "junior",
  "senior",
  "staff",
  "principal",
  "freelance",
  "veteran",
];
const COLLEAGUE_ROLES = ["tester", "developer", "debugger", "reviewer"];
const COLLEAGUE_CHATS = [
  "Hi there, fellow bug hunter!",
  "I wonder how many layers this codebase has...",
  "Some bugs in here put up a pretty hard fight!",
  "Look out for coffee, it might save your butt.",
  "So, you are also looking for that dormant feature?",
  "A handy debugger is better than a clunky one.",
  "I used to be a tester like you. But then I took an edge case to the knee...",
];

const TOP_LAYER_CHATS = [
  "Careful! The Bug has crushed everyone who tried to debug it.",
  "We only have one rule here: don't poke the Bug!",
  "Nobody has managed to fix it yet. Maybe you will?",
  "Sssh! The feature is dormant, and the Bug is guarding it.",
  "I see, another lucky bug hunter!",
];

// A being that acts on its own. Its `ai` flags say whether it attacks the
// player and whether it moves at all. Every autonomous being carries one
// bug report so there is always something to collect.
class Autonomous extends Being {
  constructor(visual) {
    super(visual);
    this.ai = {
      hostile: RNG.getUniform() < rules.HOSTILE_CHANCE,
      mobile: true,
    };
    this.inventory.addItem(new items.BugReport());
  }

  act() {
    return ai.act(this);
  }

  getChat() {
    return null;
  }
}

// Harmless on its own, but there are so many of them.
export class Typo extends Autonomous {
  constructor() {
    super({ ch: "t", fg: "#aaa", name: "typo" });
    this.mana = this.maxmana = 0;
    this.hp = this.maxhp = 1;
  }
}
Typo.danger = 1;

// Flits about and is mostly ignored.
export class Warning extends Autonomous {
  constructor() {
    super({ ch: "w", fg: "#a83", name: "warning" });
    this.mana = this.maxmana = 0;
    this.hp = this.maxhp = 10;
  }
}
Warning.danger = 1;

