// Rooted to the spot, and fails whenever it feels like it.
export class FlakyTest extends Autonomous {
  constructor() {
    super({ ch: "f", fg: "#3c3", name: "flaky test" });
    this.hp = this.maxhp = 30;
    this.mana = this.maxmana = 30;
    this.defense = 15;
    this.ai.mobile = false;
  }
}
FlakyTest.danger = 8;

// A fellow bug hunter: never hostile, randomly named and coloured, and
// happy to chat. Colleagues have no danger rating; the decorator places
// them deliberately.
export class Colleague extends Autonomous {
  constructor() {
    let level = RNG.getItem(COLLEAGUE_LEVELS);
    let role = RNG.getItem(COLLEAGUE_ROLES);
    let visual = {
      ch: role.charAt(0),
      fg: Color.toRGB([
        RNG.getUniformInt(100, 255),
        RNG.getUniformInt(100, 255),
        RNG.getUniformInt(100, 255),
      ]),
      name: `${level} ${role}`,
    };
    super(visual);
    this.sex = 2;
    this.ai.hostile = false;
  }

  getChat() {
    if (this._level && this._level.danger == rules.LAST_LEVEL) {
      return RNG.getItem(TOP_LAYER_CHATS);
    }

    return RNG.getItem(COLLEAGUE_CHATS);
  }
}

// The Bug itself: the one that put the feature to sleep. It squats on the
// top layer, never moves, and fights back hard. Crushing it ends the hunt.
// It has no danger rating, so the factory never produces another.
export class TheBug extends Autonomous {
  constructor() {
    super({ ch: "B", fg: "#f00", name: "Bug" });
    this.hp = this.maxhp = rules.BUG_HP;
    this.mana = this.maxmana = rules.BUG_MANA;
    this.attack = rules.BUG_ATTACK;
    this.defense = rules.BUG_DEFENSE;
    this.ai.hostile = true;
    this.ai.mobile = false;
  }

  // There is only one, so it is always "the Bug".
  describeThe() {
    return "the Bug";
  }

  describeA() {
    return "the Bug";
  }

  die() {
    super.die();
    pubsub.publish("bug-defeated", this);
  }
}
